// Exercise util::fail_guard with a noexcept cleanup action and both enable/disable paths.
// We assert that the action only runs when not disabled.
{
  // Counter mutated by the guard's cleanup action.
  int counter = 0;

  // Randomly decide whether to disable the guard before scope exit.
  bool disable_flag = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;

  // The callable must be invocable with no args and ideally noexcept in a destructor context.
  auto cleanup = [&counter]() noexcept { counter++; };

  // Create the fail guard; it takes ownership of the callable by move.
  auto guard = util::fail_guard(std::move(cleanup));

  // Optionally disable so cleanup will not run at destruction time.
  if (disable_flag) {
    guard.disable();
  }

  // Guard goes out of scope here; destructor runs, invoking cleanup iff not disabled.
  (void)0;

  // Validate expected behavior.
  if (disable_flag) {
    FUZZ_ASSERT(counter == 0, "fail_guard: cleanup ran despite disable()");
  } else {
    FUZZ_ASSERT(counter == 1, "fail_guard: cleanup did not run when enabled");
  }
}
// Validation: Stub ensures callable validity, toggles disable path, and asserts post-conditions.

// Append a trivially-copyable struct (util::point_t) into a byte buffer.
// Requirements: buf is modifiable; T is treated as raw bytes; lifetime of value covers the call.
{
  std::vector<uint8_t> buf;
  buf.reserve(64);

  // Use the provided point object as the value to append (trivially copyable: two doubles).
  const std::size_t before = buf.size();
  util::append_struct(buf, *point);
  const std::size_t after = buf.size();

  // Validate that exactly sizeof(T) bytes were appended.
  FUZZ_ASSERT(after == before + sizeof(*point), "append_struct: size did not grow by sizeof(T)");
}
// Validation: Uses provided util::point_t, checks buffer growth; does not free input so returns it as output.

// Format raw bytes of a value as uppercase hex via util::hex; consume both rev orders.
// T is read as raw bytes; using trivially copyable uuid_util::uuid_t.
{
  bool rev = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
  auto hx = util::hex(*uuid, rev);
  // Convert to text to exercise the wrapper; to_string_view is expected to be provided by Hex<T>.
  auto sv = hx.to_string_view();
  // Basic sanity: hex string length should be sizeof(T)*2.
  FUZZ_ASSERT(sv.size() == sizeof(*uuid) * 2, "hex: unexpected hex length");
}
// Validation: Exercises both rev paths and validates output length; input uuid is preserved as output.

// log_hex should produce a string prefixed with 0x and hex of the raw bytes.
{
  std::string s = util::log_hex(*uuid);
  // Minimal validation: non-empty and begins with expected prefix.
  FUZZ_ASSERT(!s.empty(), "log_hex: empty result");
  FUZZ_ASSERT(s.size() >= 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X'), "log_hex: missing 0x prefix");
}
// Validation: Calls template with uuid value and preserves input for future stubs.

// Convert a byte range to hex using random-access iterators with both emission orders.
{
  // Source bytes from fuzz string; limit size for performance.
  std::string data = FUZZ_PARAM_STR();
  if (data.size() > 1024) data.resize(1024);
  std::vector<uint8_t> bytes(data.begin(), data.end());

  bool rev = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
  std::string hx = util::hex_vec(bytes.begin(), bytes.end(), rev);
  // Expect exactly 2 hex chars per byte.
  FUZZ_ASSERT(hx.size() == bytes.size() * 2, "hex_vec: unexpected hex size");
}
// Validation: Uses vector<uint8_t> iterators and checks size property.

// Parse a hex string into a trivially copyable type; exercise both rev orders.
{
  std::string s = FUZZ_PARAM_STR();
  if (s.size() > 1024) s.resize(1024);
  bool rev = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;

  // Use uint64_t as T; well-defined object representation and size.
  uint64_t v = util::from_hex<uint64_t>(std::string_view{s}, rev);
  (void)v; // value is unspecified beyond size/padding rules; just ensure call succeeds.
}
// Validation: Covers parsing path with arbitrary input and rev flag.

// Parse hex-encoded characters into a byte string; exercise rev flag.
{
  std::string hex = FUZZ_PARAM_STR();
  if (hex.size() > 2048) hex.resize(2048);
  bool rev = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
  std::string bytes = util::from_hex_vec(hex, rev);
  // Output length equals floor(count(hex digits)/2). We can't easily count here without reimplementing;
  // minimally assert that the size is plausible (<= hex.size()/2).
  FUZZ_ASSERT(bytes.size() <= hex.size() / 2, "from_hex_vec: output too large");
}
// Validation: Invokes function on arbitrary input and checks a conservative size bound.

// Access the underlying representation of an enum by reference.
{
  enum class Color : std::int16_t { A = -3, B = 0, C = 7 };
  // Pick a value randomly.
  unsigned pick = *FUZZ_PARAM(unsigned int) % 3u;
  Color c = (pick == 0 ? Color::A : (pick == 1 ? Color::B : Color::C));
  const std::underlying_type_t<Color> &u = util::enm(c);
  FUZZ_ASSERT(u == static_cast<std::underlying_type_t<Color>>(c), "enm: underlying mismatch");
}
// Validation: Ensures returned reference matches enum's underlying value.

// Parse integer from [begin, end) character range.
{
  std::string s = FUZZ_PARAM_STR();
  // Keep it small and ASCII-ish to exercise typical paths.
  for (char &ch : s) {
    unsigned r = *FUZZ_PARAM(unsigned int) % 12u;
    if (r == 0) ch = '-';
    else if (r <= 10) ch = char('0' + (r - 1));
    else ch = 'x'; // occasional non-digit
  }
  if (s.size() > 64) s.resize(64);
  const char *begin = s.data();
  const char *end = s.data() + s.size();
  volatile std::int64_t v = util::from_chars(begin, end);
  (void)v;
}
// Validation: Supplies a valid contiguous range and avoids overflow checks per contract.

// Parse integer from a std::string_view by delegating to from_chars.
{
  std::string s = FUZZ_PARAM_STR();
  // Create a numeric-like string with possible leading '-'.
  if (!s.empty()) {
    s[0] = ((*FUZZ_PARAM(unsigned int)) & 1u) ? '-' : '0' + ((*FUZZ_PARAM(unsigned int)) % 10u);
    for (std::size_t i = 1; i < s.size(); ++i) s[i] = '0' + ((*FUZZ_PARAM(unsigned int)) % 10u);
  }
  if (s.size() > 64) s.resize(64);
  std::int64_t v = util::from_view(std::string_view{s});
  (void)v;
}
// Validation: Provides valid view and exercises parsing including empty case handling.

// Return either the optional value (if engaged) or the provided fallback.
{
  using T = int;
  bool engaged = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
  T fallback = static_cast<T>(*FUZZ_PARAM(int));
  std::optional<T> opt;
  if (engaged) opt = static_cast<T>(*FUZZ_PARAM(int));

  T res = util::either(std::move(opt), std::move(fallback));
  if (engaged) {
    FUZZ_ASSERT(res == *opt, "either: expected optional value");
  } else {
    FUZZ_ASSERT(res == fallback, "either: expected fallback value");
  }
}
// Validation: Covers both branches and asserts result consistency.

// Free C-allocated memory using util::c_free.
{
  // Allocate a small buffer with malloc (compatible with free()).
  std::size_t n = (*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
  void *p = std::malloc(n);
  if (!p) { FUZZ_BAIL(); }

  // Optionally write some data to ensure the pointer is live.
  std::memset(p, *FUZZ_PARAM(int), static_cast<int>(n < 64 ? n : 64));

  // Free via util::c_free; do not use pointer afterwards.
  util::c_free(static_cast<unsigned char*>(p));
}
// Validation: Uses malloc-compatible allocation and frees exactly once.

// Create a string_view over a contiguous byte range.
{
  std::string s = FUZZ_PARAM_STR();
  if (s.size() > 1024) s.resize(1024);
  // Use the raw bytes of s via pointers (byte-addressable and contiguous).
  const unsigned char *begin = reinterpret_cast<const unsigned char*>(s.data());
  const unsigned char *end = begin + s.size();
  std::string_view sv = util::view(begin, end);
  FUZZ_ASSERT(sv.size() == s.size(), "view: size mismatch");
  // Ensure the data matches at least first byte when non-empty.
  if (!s.empty()) { FUZZ_ASSERT(sv.data()[0] == s[0], "view: content mismatch at 0"); }
}
// Validation: Supplies valid contiguous range and validates size/content.

// Byte-swap to little-endian; applying twice should be identity for any platform.
{
  uint32_t x = *FUZZ_PARAM(uint32_t);
  uint32_t y = util::endian::little(x);
  uint32_t z = util::endian::little(y);
  FUZZ_ASSERT(z == x, "endian::little: not an involution when applied twice");

  // Also exercise optional path.
  std::optional<uint16_t> ox;
  if (((*FUZZ_PARAM(unsigned int)) & 1u) != 0u) ox = static_cast<uint16_t>(*FUZZ_PARAM(uint16_t));
  auto oy = util::endian::little(ox);
  auto oz = util::endian::little(oy);
  FUZZ_ASSERT(oz.has_value() == ox.has_value(), "endian::little: optional engagement mismatch");
  if (ox && oz) { FUZZ_ASSERT(*oz == *ox, "endian::little: optional value mismatch after double-apply"); }
}
// Validation: Tests involution property by double-application and covers optional case.

// Byte-swap to big-endian; applying twice should be identity for any platform.
{
  uint64_t x = *FUZZ_PARAM(uint64_t);
  uint64_t y = util::endian::big(x);
  uint64_t z = util::endian::big(y);
  FUZZ_ASSERT(z == x, "endian::big: not an involution when applied twice");

  // Optional path as well.
  std::optional<uint32_t> ox;
  if (((*FUZZ_PARAM(unsigned int)) & 1u) != 0u) ox = static_cast<uint32_t>(*FUZZ_PARAM(uint32_t));
  auto oy = util::endian::big(ox);
  auto oz = util::endian::big(oy);
  FUZZ_ASSERT(oz.has_value() == ox.has_value(), "endian::big: optional engagement mismatch");
  if (ox && oz) { FUZZ_ASSERT(*oz == *ox, "endian::big: optional value mismatch after double-apply"); }
}
// Validation: Verifies double-application identity and exercises optional handling.

// Format UUID as canonical hyphenated hex string.
{
  std::string s = uuid->string();
  // Validate canonical form: 36 chars and hyphens at 8-4-4-4-12 positions.
  FUZZ_ASSERT(s.size() == 36, "uuid.string: unexpected size");
  FUZZ_ASSERT(s[8] == '-' && s[13] == '-' && s[18] == '-' && s[23] == '-', "uuid.string: bad hyphen positions");
}
// Validation: Calls const method on valid input and preserves object for further use.

// Construct a util::point_t with fuzzed coordinates and return a managed heap object.
util::point_t *point = nullptr; // must be visible after this block for runtime assignment
{
  double x = *FUZZ_PARAM(double);
  double y = *FUZZ_PARAM(double);

  // Allocate and initialize; use nothrow and bail on failure.
  util::point_t *p = new (std::nothrow) util::point_t();
  if (!p) { FUZZ_BAIL(); }
  p->x = x;
  p->y = y;

  // Sanity: streaming should produce some text; ensures object is usable.
  std::ostringstream oss;
  oss << *p;
  FUZZ_ASSERT(!oss.str().empty(), "point_t stream output empty");

  point = p; // publish to output variable
}
// Ensure output is initialized and non-null for the fuzzer runtime.
FUZZ_ASSERT(point != nullptr, "point_t: output was not initialized");
// Validation: Allocates, initializes, and validates formatting; publishes non-null output.

// Construct a uuid_util::uuid_t via the API generator and return it as a heap object.
uuid_util::uuid_t *uuid = nullptr; // must be visible after this block for runtime assignment
{
  uuid_util::uuid_t gen = uuid_util::uuid_t::generate();

  // Allocate with nothrow; bail on failure.
  uuid_util::uuid_t *u = new (std::nothrow) uuid_util::uuid_t(gen);
  if (!u) { FUZZ_BAIL(); }

  // Validate canonical textual form for quick sanity.
  std::string s = u->string();
  FUZZ_ASSERT(s.size() == 36, "uuid_t::string: unexpected size");
  FUZZ_ASSERT(s[8] == '-' && s[13] == '-' && s[18] == '-' && s[23] == '-', "uuid_t::string: hyphen positions incorrect");

  uuid = u; // publish to output variable
}
// Ensure output is initialized and non-null for the fuzzer runtime.
FUZZ_ASSERT(uuid != nullptr, "uuid_t: output was not initialized");
// Validation: Uses official generator, ensures allocation success, and checks canonical UUID text shape.

