import os
import random
from typing import List

# This generator targets fuzzers that consume arbitrary byte strings via FUZZ_PARAM_STR
# and interpret them as raw bytes (no specific structure required). The stubs under test
# are util::hex_vec (expects any bytes, validates hex length) and util::view (expects
# contiguous bytes and validates size/content). We therefore generate diverse, valid
# byte sequences with varying sizes and content patterns to exercise different code paths
# such as empty input, small inputs, large inputs, repeated patterns, ascending/descending
# sequences, full 0x00/0xFF ranges, and random distributions. All outputs are <= 4096 bytes.

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    # Generate uniformly random bytes
    return bytes(rng.getrandbits(8) for _ in range(n))

def _ascending(n: int) -> bytes:
    return bytes((i % 256 for i in range(n)))

def _descending(n: int) -> bytes:
    return bytes(((255 - i) % 256 for i in range(n)))

def _repeat_byte(b: int, n: int) -> bytes:
    return bytes([b] * n)

def _alternating(b1: int, b2: int, n: int) -> bytes:
    if n <= 0:
        return b""
    pattern = bytes([b1, b2])
    full, rem = divmod(n, 2)
    data = pattern * full
    if rem:
        data += bytes([b1])
    return data

def _blocks(patterns: List[bytes], total: int) -> bytes:
    out = bytearray()
    if total <= 0:
        return b""
    i = 0
    while len(out) < total:
        p = patterns[i % len(patterns)]
        need = total - len(out)
        if len(p) <= need:
            out += p
        else:
            out += p[:need]
        i += 1
    return bytes(out)

def _zipf_bytes(rng: random.Random, n: int) -> bytes:
    # Skewed distribution favoring small byte values to vary hex output
    # Simple geometric-like distribution capped at 255
    res = bytearray()
    while len(res) < n:
        # Probability halves each increment; clamp to 0..255
        x = 0
        # Use up to 8 steps to avoid long loops
        for _ in range(8):
            if rng.random() < 0.5:
                break
            x += 1
        res.append(x & 0xFF)
    return bytes(res)

def _choose_size(rng: random.Random) -> int:
    # Favor a range up to 1024 specifically (the stubs clamp at 1024),
    # occasionally produce very small or empty, and sometimes near the cap.
    roll = rng.random()
    if roll < 0.10:
        return 0
    if roll < 0.25:
        return rng.randint(1, 15)
    if roll < 0.85:
        return rng.randint(16, 1024)
    # Occasionally exceed 1024 slightly; the stub will truncate, exercising resize path
    return rng.randint(1025, 1500)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    n = _choose_size(rng)

    # Select a content strategy
    strategies = []
    # Always include a pool of deterministic and random patterns
    strategies.append(lambda: _rand_bytes(rng, n))
    strategies.append(lambda: _ascending(n))
    strategies.append(lambda: _descending(n))
    strategies.append(lambda: _repeat_byte(0x00, n))
    strategies.append(lambda: _repeat_byte(0xFF, n))
    strategies.append(lambda: _repeat_byte(0x7F, n))
    strategies.append(lambda: _alternating(0x00, 0xFF, n))
    strategies.append(lambda: _alternating(0x55, 0xAA, n))
    strategies.append(lambda: _zipf_bytes(rng, n))

    # Mixed block patterns to create structured sequences
    patterns_pool = [
        bytes(range(256)),
        bytes(reversed(range(256))),
        b"\x00" * 64,
        b"\xFF" * 64,
        b"\x55\xAA" * 32,
        b"\xDE\xAD\xBE\xEF" * 16,
        b"0123456789ABCDEF" * 8,
    ]

    strategies.append(lambda: _blocks([patterns_pool[int(rng.random() * len(patterns_pool))] for _ in range(3)], n))

    choice = rng.randrange(len(strategies))
    data = strategies[choice]()

    # Ensure upper bound per requirements
    if len(data) > 4096:
        data = data[:4096]

    return data

import random
import string
from typing import List

# Generator for hex-encoded strings to exercise util::from_hex and util::from_hex_vec
# The fuzzer uses FUZZ_PARAM_STR for input. We'll return a bytes object containing
# a text payload that includes diverse, valid hex encodings and patterns, including:
# - Clean hex sequences of varying lengths (even/odd)
# - Mixed-case hex
# - Junk separators and non-hex characters interspersed
# - Long runs to hit truncation bounds (<= 2048 to match fuzzer caps)
# - Optional reversed-interesting layouts (though rev is chosen by fuzzer flag)
# - Grouped UUID-like 8-4-4-4-12 patterns, continuous hex, spaced hex, comma-separated, etc.

HEX_DIGITS_LOWER = "0123456789abcdef"
HEX_DIGITS_UPPER = "0123456789ABCDEF"
HEX_DIGITS_MIXED = HEX_DIGITS_LOWER + HEX_DIGITS_UPPER
NON_HEX = [
    " ", "\t", "\n", "\r", "-", ":", ",", ".", ";", "_", "/", "|", "*", "+", "#",
    "G", "Z", "g", "z", "x", "X", "0x", "0X"
]


def rnd_hex(run_len: int, rng: random.Random, mixed_case: bool = True) -> str:
    digits = HEX_DIGITS_MIXED if mixed_case else HEX_DIGITS_LOWER
    return "".join(rng.choice(digits) for _ in range(run_len))


def uuid_like(rng: random.Random) -> str:
    # 8-4-4-4-12 uppercase
    parts = [8, 4, 4, 4, 12]
    return "-".join(rnd_hex(n, rng, mixed_case=True) for n in parts)


def spaced_pairs(byte_count: int, rng: random.Random) -> str:
    # Emit bytes as two hex digits separated by spaces, tabs, mixed spacing
    out: List[str] = []
    for i in range(byte_count):
        pair = rnd_hex(2, rng)
        out.append(pair)
        if i + 1 < byte_count:
            out.append(rng.choice([" ", "  ", "\t", ",", ";", " ", "\n"]))
    return "".join(out)


def mixed_junk(hex_len: int, rng: random.Random) -> str:
    # Insert random junk between hex digits; ensure resulting string has at least hex_len hex digits
    # We'll create hex_len hex digits and randomly sprinkle junk tokens
    tokens: List[str] = []
    for i in range(hex_len):
        tokens.append(rnd_hex(1, rng))
        if rng.random() < 0.4:
            tokens.append(rng.choice(NON_HEX))
    # Occasionally prefix/suffix non-hex
    if rng.random() < 0.5:
        tokens.insert(0, rng.choice(NON_HEX))
    if rng.random() < 0.5:
        tokens.append(rng.choice(NON_HEX))
    return "".join(tokens)


def odd_length_hex(total_digits: int, rng: random.Random) -> str:
    # Ensure odd count of hex digits, optionally with separators
    if total_digits % 2 == 0:
        total_digits += 1
    return mixed_junk(total_digits, rng)


def continuous_hex(byte_count: int, rng: random.Random) -> str:
    # Pure hex without separators
    return rnd_hex(byte_count * 2, rng)


def prefixed_hex(byte_count: int, rng: random.Random) -> str:
    # Mix of 0x-prefixed pairs and plain pairs, with commas/spaces
    parts: List[str] = []
    for i in range(byte_count):
        pair = rnd_hex(2, rng)
        if rng.random() < 0.6:
            parts.append(rng.choice(["0x", "0X"]) + pair)
        else:
            parts.append(pair)
        if i + 1 < byte_count:
            parts.append(rng.choice([",", ", ", " ", "; "]))
    return "".join(parts)


def alternating_case(hex_len: int, rng: random.Random) -> str:
    s = rnd_hex(hex_len, rng)
    out = []
    upper = True
    for ch in s:
        if ch.isalpha():
            out.append(ch.upper() if upper else ch.lower())
            upper = not upper
        else:
            out.append(ch)
    return "".join(out)


def bounded_concat(parts: List[str], max_len: int) -> str:
    out = []
    total = 0
    for p in parts:
        if total + len(p) > max_len:
            rem = max_len - total
            if rem <= 0:
                break
            out.append(p[:rem])
            total += rem
            break
        out.append(p)
        total += len(p)
    return "".join(out)


def build_payload(rng: random.Random) -> str:
    # Assemble a composite payload mixing various patterns separated by newlines.
    # The fuzzer may truncate to 1024 or 2048 depending on target; we keep <= 2048.
    max_total = rng.choice([512, 768, 1024, 1536, 2048])

    segments: List[str] = []

    # 1) UUID-like
    segments.append(uuid_like(rng))

    # 2) Continuous long hex
    segments.append(continuous_hex(rng.randint(4, 64), rng))

    # 3) Odd-length hex digits with junk
    segments.append(odd_length_hex(rng.randint(5, 127), rng))

    # 4) Spaced pairs
    segments.append(spaced_pairs(rng.randint(4, 64), rng))

    # 5) Prefixed hex
    segments.append(prefixed_hex(rng.randint(4, 40), rng))

    # 6) Alternating case continuous
    segments.append(alternating_case(rng.randint(8, 150), rng))

    # 7) Extra junk-only lines to test skipping
    junk_line = "".join(rng.choice(NON_HEX) for _ in range(rng.randint(5, 30)))
    segments.append(junk_line)

    # 8) Another UUID-like but lowercase/mixed
    segments.append(uuid_like(rng).lower())

    # 9) Mixed junk with many hex digits to build sizable output
    segments.append(mixed_junk(rng.randint(64, 400), rng))

    # Join with newlines and some random separators
    glue_choices = ["\n", "\r\n", "\n--\n", "\n::\n"]
    glued = []
    for i, seg in enumerate(segments):
        glued.append(seg)
        if i + 1 < len(segments):
            glued.append(rng.choice(glue_choices))

    payload = bounded_concat(glued, max_total)

    # Ensure not empty
    if not payload:
        payload = "0"  # minimal hex nibble (parser tolerates odd nibble)

    return payload


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Randomly choose a strategy mix bias to vary distributions across seeds
    # But ultimately build a composite payload to cover many parser behaviors
    payload = build_payload(rng)

    # Return as bytes; the fuzzer expects std::string data
    return payload.encode("utf-8")
